"""Package real Kobweb release assets as a complete client-rendered static site.

Transparent fallback, not Kobweb's browser-prerendered export. --refresh-existing
reapplies packaging only when every recorded source input is still unchanged;
it never substitutes current compiler output or claims a build of changed sources.
"""
from pathlib import Path
from datetime import datetime
from zoneinfo import ZoneInfo
import argparse
import hashlib
import json
import re
import shutil
import sys
from product_assets import CONTRACT, LEGAL_INPUTS, allowed_asset

parser = argparse.ArgumentParser()
parser.add_argument('--base-path', default='/')
parser.add_argument('--refresh-existing', action='store_true')
parser.add_argument('--output-dir', type=Path)
parser.add_argument('--source-inputs', type=Path)
args = parser.parse_args()
base = args.base_path
if not re.fullmatch(r'/(?:[A-Za-z0-9_-]+/)*', base):
    parser.error('Invalid deployment base path.')
root = Path(__file__).resolve().parents[1]
repo = root.parents[1]
resources = root / 'site/build/processedResources/js/main/public'
production = root / 'site/build/kotlin-webpack/js/productionExecutable'
container = args.output_dir or root / ('dist-run-two' if base == '/' else 'dist-run-two-subpath')
output = container if base == '/' else container / base.strip('/')
owner = container / '.materiewellen-generated'
input_hashes = json.loads(args.source_inputs.read_text()) if args.source_inputs else None
if args.refresh_existing:
    if not owner.is_file() or not (output / 'manifest.json').is_file():
        raise SystemExit('Refusing to refresh an unowned or incomplete output.')
    existing = json.loads((output / 'manifest.json').read_text())
    expected_base = existing['deployment_base']
    if expected_base != base:
        raise SystemExit('Existing manifest does not match requested base path.')
    sys.path.insert(0, str(repo / 'tools/build'))
    from build_inputs import product_input_hashes
    recorded_inputs = existing.get('input_hashes')
    if (not recorded_inputs or recorded_inputs != product_input_hashes(repo)
            or (input_hashes is not None and input_hashes != recorded_inputs)):
        raise SystemExit('Source inputs changed or provenance is missing; perform a fresh build.')
    input_hashes = recorded_inputs
else:
    if not isinstance(input_hashes, dict) or not input_hashes:
        raise SystemExit('A fresh export requires the source-input manifest recorded by build-static.sh.')
    index = resources / 'index.html'
    main = production / 'materiewellen.js'
    if not index.is_file() or not main.is_file():
        raise SystemExit('Missing Kobweb-generated index or release JS. Run build-static.sh first.')
    if f'src="{base}materiewellen.js"' not in index.read_text():
        raise SystemExit('Generated entrypoint belongs to another base path; rebuild first.')
    if container.exists() and any(container.iterdir()):
        raise SystemExit('Refusing to overwrite existing output. Choose a fresh --output-dir.')
    output.mkdir(parents=True, exist_ok=True)
    for source_root in (resources, production):
        for file in source_root.rglob('*'):
            if not file.is_file():
                continue
            name = file.relative_to(source_root).as_posix()
            if not allowed_asset(name):
                continue
            if file.is_symlink() or not file.resolve().is_relative_to(source_root.resolve()):
                raise SystemExit('Symlink resource is not an export input: ' + name)
            target = output / name
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(file, target)
    owner.write_text('Generated by scripts/export-spa.py; reproducible using build-static.sh.\n')

for name, source_name in LEGAL_INPUTS.items():
    source = repo / source_name
    if source.is_symlink() or not source.resolve().is_relative_to(repo.resolve()):
        raise SystemExit('Symlink legal notice is not an export input: ' + source_name)
    if input_hashes.get(source_name) != hashlib.sha256(source.read_bytes()).hexdigest():
        raise SystemExit('Legal notice changed after the recorded build: ' + source_name)
    target = output / name
    target.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(source, target)

index = output / 'index.html'
markup = index.read_text()
if f'src="{base}materiewellen.js"' not in markup:
    raise SystemExit('Output entrypoint does not match the requested base path.')
# The generated default favicon has no asset in this project. An explicit empty
# data URL suppresses that pointless request without inventing a branding asset.
markup, count = re.subn(r'<link href="[^"]*" rel="icon">', '<link href="data:," rel="icon">', markup)
if count != 1:
    raise SystemExit('Expected one generated favicon link; inspect the current Kobweb HTML.')
index.write_text(markup)
for script in output.glob('*.js'):
    script.write_text(re.sub(r'(?m)^\s*//# sourceMappingURL=.*$', '', script.read_text()))
# Explicitly bypass Jekyll for branch/folder-based static hosting. Actions-based
# Pages artifact deployment serves these files directly and also accepts this.
(output / '.nojekyll').write_text('')
manifest = {
    'product_contract': CONTRACT,
    'input_hashes': input_hashes,
    'mode': 'complete static single-page application, rendered in browser; no prerendering claim',
    'reason': 'Kobweb 0.23.3 native export uses Playwright 1.55 managed Chromium and exposes no executablePath; the official browser CDN is blocked by the environment proxy (HTTP 403), reconfirmed 2026-10-12. Installed system Chromium is used only for QA.',
    'created_at': datetime.now(ZoneInfo('Europe/Berlin')).isoformat(),
    'public_deployment': False,
    'deployment_base': base,
    'packaging_adjustment': 'Unused favicon replaced by data:,; source-map references removed; positive product asset selection applied.',
    'files': {str(f.relative_to(output)): {'bytes': f.stat().st_size, 'sha256': hashlib.sha256(f.read_bytes()).hexdigest()}
              for f in sorted(output.rglob('*')) if f.is_file() and str(f.relative_to(output)) not in {'.materiewellen-generated', 'manifest.json'}},
}
(output / 'manifest.json').write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + '\n')
print('Complete SPA output:', output)
print('Serve directory:', container, 'and open path:', base)
print('Files:', len(manifest['files']), 'release JS bytes:', (output / 'materiewellen.js').stat().st_size)
